sql.where:
p.deleted = 0



    AND p.park_id = #{reqVO.parkId}


    AND p.name LIKE CONCAT('%', #{reqVO.name}, '%')


    AND p.address LIKE CONCAT('%', #{reqVO.address}, '%')


    AND p.area_code = #{reqVO.areaCode}


    AND p.cleaning_frequency = #{reqVO.cleaningFrequency}


    AND p.green_maintenance_cycle = #{reqVO.greenMaintenanceCycle}


    AND p.manager_id = #{reqVO.managerId}


    AND p.operation_status_id = #{reqVO.operationStatusId}


    AND p.vehicle_id = #{reqVO.vehicleId}


    AND p.report_by = #{reqVO.reportBy}


    AND p.plan_status_id = #{reqVO.planStatusId}


    AND p.task_type_id = #{reqVO.taskTypeId}




    AND p.cleaning_standard LIKE CONCAT('%', #{reqVO.cleaningStandard}, '%')


    AND p.green_maintenance_content LIKE CONCAT('%', #{reqVO.greenMaintenanceContent}, '%')


    AND p.waste_transfer_frequency LIKE CONCAT('%', #{reqVO.wasteTransferFrequency}, '%')


    AND p.facility_location LIKE CONCAT('%', #{reqVO.facilityLocation}, '%')


    AND p.facility_damage_desc LIKE CONCAT('%', #{reqVO.facilityDamageDesc}, '%')




    AND p.waste_collection_points = #{reqVO.wasteCollectionPoints}





        AND p.waste_transfer_time >= #{reqVO.wasteTransferTime[0]}


        AND p.waste_transfer_time <= #{reqVO.wasteTransferTime[1]}




        AND p.report_time >= #{reqVO.reportTime[0]}


        AND p.report_time <= #{reqVO.reportTime[1]}




        AND p.create_time >= #{reqVO.createTime[0]}


        AND p.create_time <= #{reqVO.createTime[1]}





    AND JSON_OVERLAPS(CAST(p.staff_ids AS JSON), CAST(#{reqVO.staffIds} AS JSON))


    AND JSON_OVERLAPS(CAST(p.green_type_ids AS JSON), CAST(#{reqVO.greenTypeIds} AS JSON))


    AND JSON_OVERLAPS(CAST(p.green_staff_ids AS JSON), CAST(#{reqVO.greenStaffIds} AS JSON))


    AND JSON_OVERLAPS(CAST(p.facility_ids AS JSON), CAST(#{reqVO.facilityIds} AS JSON))
